def rep(src, old, new, count=1, name=""):
    n = src.count(old)
    if n != count:
        raise SystemExit("[FAIL] %s: expected %d, found %d" % (name, count, n))
    return src.replace(old, new)

data = json.load(io.open(DATASET, "r", encoding="utf-8"))
records = []
for i in IDX:
    d = data[i]
    records.append({"instruction": d["instruction"], "input": d.get("input", ""), "output": d["output"]})
for q, a in CUSTOM:
    records.append({"instruction": q, "input": "", "output": a})
seen, uniq = set(), []
for r in records:
    if r["instruction"] not in seen:
        seen.add(r["instruction"]); uniq.append(r)
assert len(uniq) == 50, "expect 50, got %d" % len(uniq)

src = io.open(EVAL_SCRIPT, "r", encoding="utf-8").read()
src = rep(src, 'EVAL_FILE = r"D:\\ai_learning\\data\\staff_qa_eval_large.json"', 'EVAL_FILE = r"D:\\ai_learning\\data\\staff_qa_eval_50.json"', 1, "eval:file")
src = rep(src, 'data = json.load(open(EVAL_FILE, encoding="utf-8"))[:20]', 'data = json.load(open(EVAL_FILE, encoding="utf-8"))[:int(os.environ.get("EVAL_COUNT", "50"))]', 1, "eval:count")
compile(src.lstrip("\ufeff"), EVAL_SCRIPT, "exec")

with io.open(OUT, "w", encoding="utf-8") as f:
    json.dump(uniq, f, ensure_ascii=False, indent=2)
with io.open(EVAL_SCRIPT, "w", encoding="utf-8", newline="\n") as f:
    f.write(src)
print("OK: eval set written ->", OUT)
print("OK: eval_ragas.py now uses 50 entries")
